referenceSolutions.javascript:
export function nonOverlappingIntervals(intervals            )         {
const a=intervals.map(x=>[...x]).sort((x,y)=>x[1]-y[1]);let end=-Infinity,kept=0;for(const [s,e]of a)if(s>=end){kept++;end=e;}return a.length-kept;
}

